import{z as i,x as s,o as B,c as m,q as r,j as l,D as e,d as A,s as n,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"执行算法的谱系深钻","description":"","frontmatter":{"title":"执行算法的谱系深钻","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ex-algo-taxonomy-deep.md","filePath":"quant/ex-algo-taxonomy-deep.md","lastUpdated":1791413859000}'),p={name:"quant/ex-algo-taxonomy-deep.md"};function d(h,a,D,c,u,f){const t=s("Mermaid");return B(),m("div",null,[a[2]||(a[2]=r('<h1 id="执行算法的谱系深钻" tabindex="-1">执行算法的谱系深钻 <a class="header-anchor" href="#执行算法的谱系深钻" aria-label="Permalink to &quot;执行算法的谱系深钻&quot;">​</a></h1><div class="epigraph"><p>算法名称是销售标签，谱系是维度空间：先把「参照什么、按什么走、用什么单、去哪些场所、看哪些状态」写清楚，评价与复现才有可能。</p><footer>—— 据 Harris, *Trading and Exchanges* 对执行方式与经纪商选择的论述；Kissell, *The Science of Algorithmic Trading and Portfolio Management* 整理</footer></div><p><a href="/quant/mm-regulation-map">上一课</a>以监管义务收束做市课程：义务与限额共用引擎接口，撤单流要同时回答风险管理与监管两套语言。做市在簿的对面供给流动性；本课程换到需求侧——一张母单如何在限价簿、暗池与竞价里换成头寸而不多付钱。主干已逐个写过 <a href="/quant/twap-vwap-pov">TWAP / VWAP / POV</a>、<a href="/quant/adaptive-pov">自适应 POV</a>、<a href="/quant/arrival-price">到达价格算法</a>与 <a href="/quant/cks-optimal-placement">Cont–Kukanov–Stoikov 最优挂单</a>；缺口是谱系：经纪商名单上几十个名字，区分它们的是哪几个维度。本课立五根轴，后课沿轴深入；它不回答「哪个算法最好」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一个「VWAP」标签，在两家经纪商处可以是两种产品：一家用历史量曲线加全市价子单，另一家用实时量曲线、限价排队加暗池探量。名字只覆盖其中一小段。比较 <a href="/quant/tca">成交后分析 TCA</a>、审规格时，缺的不是更多名字，而是一组不变维度：任何执行算法都能被唯一定位，任何规格变更都能说成「沿哪根轴动了哪一格」。没有这组轴，算法比较的对象是标签而不是机制。</p><h3 id="五根轴" tabindex="-1">五根轴 <a class="header-anchor" href="#五根轴" aria-label="Permalink to &quot;五根轴&quot;">​</a></h3><p>参照轴：算法对什么负责——到达中点、窗口 VWAP、收盘价、或只对内部进度负责。参照决定激励：对 VWAP 负责的算法会被训练去贴量曲线，对到达价负责的算法才真正削减 <a href="/quant/implementation-shortfall">实施缺口</a>。</p><p><span class="marginnote">「参照轴」翻译成小白话：算法考试用的评分标准。到达价算法的考卷是「你比下单那一刻的市场价省了多少」；VWAP 算法的考卷是「你的均价有没有跑赢全市场按成交量加权的均价」。评分标准不同，行为就不同——算法总会朝着讨好考卷的方向优化。</span></p><p>决策轴：速率 \\(v_t\\) 怎么产生——静态日程、状态反馈、还是滚动最优控制。TWAP 在最左端，<a href="/quant/almgren-chriss">Almgren–Chriss 最优执行</a>的闭式轨迹居中，自适应规则靠右。</p><p>接口轴：每片子单用 taker、maker 还是混合，用不用冰山与中点单。接口决定排队风险与半价差由谁承担。</p><p>场所轴：量可以到达的集合——单所明簿、多所 <a href="/quant/smart-order-routing">智能订单路由 SOR</a>、加暗池、加竞价配额。</p><p>信息轴：条件集——只有量曲线；加盘口不平衡；加毒性或 <a href="/quant/ofi-cont">订单流不平衡 OFI</a>；加自己的成交史。</p><p><span class="marginnote">五根轴并不正交：信息轴升级常逼着决策轴升级（有了实时毒性就得有反馈通道），接口轴又限制场所轴（中点单只在部分场所存在）。按轴逐一冻结规格，比起第五个名字有用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把任何算法写成五元组 \\((B,\\mathcal{D},\\mathcal{I},\\mathcal{V},\\mathcal{S})\\)：参照 \\(B\\)、决策律 \\(\\mathcal{D}\\)、接口 \\(\\mathcal{I}\\)、场所集 \\(\\mathcal{V}\\)、状态集 \\(\\mathcal{S}\\)。成本会计给五元组配权重：参照轴决定「好」的定义与被对齐的方向；接口轴主要打半价差与排队成本，见 <a href="/quant/spread-cost">买卖价差成本</a>；场所轴打展示冲击与填成概率；信息轴与决策轴合起来打时机风险——决定算法能把缺口分布收窄到什么分辨率。</p><p>主干各课是轴上的段落：TWAP / VWAP 的 \\(\\mathcal{D}\\) 是日程、\\(\\mathcal{S}\\) 只有量曲线；自适应 POV 把 \\(\\mathcal{S}\\) 扩到进度、价差与毒性，\\(\\mathcal{D}\\) 变成规则表；到达价算法改 \\(B\\) 为 \\(M_0\\)；CKS 把 \\(\\mathcal{I}\\) 写成静态分割；SOR 展开 \\(\\mathcal{V}\\)。后课分别是轴的深入：调度深化决策轴，暗池与竞价深化场所轴，TCA 深化回到参照轴与度量。</p>',16)),(B(),l(o,null,{default:e(()=>[n(t,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20SAME%5B%22%E5%90%8C%E5%90%8D%E6%A0%87%E7%AD%BE%EF%BC%9AVWAP%22%5D%20--%3E%20BA%5B%22%E7%BB%8F%E7%BA%AA%E5%95%86%20A%20%E7%9A%84%E4%BA%A7%E5%93%81%22%5D%0A%20%20SAME%20--%3E%20BB%5B%22%E7%BB%8F%E7%BA%AA%E5%95%86%20B%20%E7%9A%84%E4%BA%A7%E5%93%81%22%5D%0A%20%20BA%20--%3E%20BA1%5B%22%E5%86%B3%E7%AD%96%EF%BC%9A%E9%9D%99%E6%80%81%E5%8E%86%E5%8F%B2%E9%87%8F%E6%9B%B2%E7%BA%BF%E6%97%A5%E7%A8%8B%22%5D%0A%20%20BA%20--%3E%20BA2%5B%22%E6%8E%A5%E5%8F%A3%EF%BC%9A%E5%85%A8%E5%B8%82%E4%BB%B7%E5%AD%90%E5%8D%95%EF%BC%8C%E5%85%A8%20taker%22%5D%0A%20%20BB%20--%3E%20BB1%5B%22%E5%86%B3%E7%AD%96%EF%BC%9A%E5%AE%9E%E6%97%B6%E9%87%8F%E6%9B%B2%E7%BA%BF%E5%8F%8D%E9%A6%88%22%5D%0A%20%20BB%20--%3E%20BB2%5B%22%E6%8E%A5%E5%8F%A3%EF%BC%9A%E9%99%90%E4%BB%B7%E6%8E%92%E9%98%9F%E5%8A%A0%E4%B8%AD%E7%82%B9%E5%8D%95%22%5D%0A%20%20BB%20--%3E%20BB3%5B%22%E5%9C%BA%E6%89%80%EF%BC%9A%E6%98%8E%E7%B0%BF%20SOR%20%E5%8A%A0%E6%9A%97%E6%B1%A0%E6%8E%A2%E9%87%8F%22%5D%0A%20%20BA1%20--%3E%20C%5B%22%E5%B9%B3%E9%9D%99%E6%97%A5%E6%88%90%E6%9C%AC%E7%9B%B8%E8%BF%91%EF%BC%8C%E6%81%90%E6%85%8C%E6%97%A5%E5%B7%AE%E5%BC%82%E4%B8%80%E6%AC%A1%E5%85%91%E7%8E%B0%22%5D%0A%20%20BB3%20--%3E%20C%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[A("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"谱系能预测行为，是因为每根轴对应一个经济对象。接口轴决定风险转移：全 taker 锁数量付价差，全 maker 省价差把完成交给队列；场所轴在「脚印」与「填成」之间换；信息轴决定条件期望的分辨率，不足时反馈会把噪声当状态。两家产品名同而轴位不同，平静日看不出差别，体制切换时分化被放大——恐慌日价差翻倍、深度撤走，接口与场所轴的差异一次兑现。轴位决定算法在极端状态下先坏在哪一格。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"maker 与 taker 的分工可以类比摆摊与扫货：挂单排队像在集市摆摊等客，省下价差但要承担「客人不来」的风险——价格跑掉、单子没成；吃单像按标价立刻买走，确定性高但要付价差。接口轴就是在「等多便宜」与「立刻拿到」之间替母单做权衡。")],-1)),(B(),l(o,null,{default:e(()=>[n(t,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E6%AF%8D%E5%8D%95%22%5D%20--%3E%20A1%5B%22%E5%8F%82%E7%85%A7%E8%BD%B4%20B%22%5D%0A%20%20M%20--%3E%20A2%5B%22%E5%86%B3%E7%AD%96%E8%BD%B4%20D%22%5D%0A%20%20M%20--%3E%20A3%5B%22%E6%8E%A5%E5%8F%A3%E8%BD%B4%20I%22%5D%0A%20%20M%20--%3E%20A4%5B%22%E5%9C%BA%E6%89%80%E8%BD%B4%20V%22%5D%0A%20%20M%20--%3E%20A5%5B%22%E4%BF%A1%E6%81%AF%E8%BD%B4%20S%22%5D%0A%20%20A1%20--%3E%20IS%5B%22%E5%88%B0%E8%BE%BE%E4%BB%B7%20%2F%20VWAP%20%2F%20%E6%94%B6%E7%9B%98%22%5D%0A%20%20A2%20--%3E%20SCH%5B%22%E9%9D%99%E6%80%81%E6%97%A5%E7%A8%8B%22%5D%0A%20%20A2%20--%3E%20FB%5B%22%E7%8A%B6%E6%80%81%E5%8F%8D%E9%A6%88%20%2F%20%E6%8E%A7%E5%88%B6%22%5D%0A%20%20A3%20--%3E%20MK%5B%22maker%20%E6%8E%92%E9%98%9F%22%5D%0A%20%20A3%20--%3E%20TK%5B%22taker%20%E5%90%83%E7%B0%BF%22%5D%0A%20%20A4%20--%3E%20LIT%5B%22%E6%98%8E%E7%B0%BF%20SOR%22%5D%0A%20%20A4%20--%3E%20DRK%5B%22%E6%9A%97%E6%B1%A0%22%5D%0A%20%20A4%20--%3E%20AUC%5B%22%E7%AB%9E%E4%BB%B7%E9%85%8D%E9%A2%9D%22%5D%0A%20%20A5%20--%3E%20ST%5B%22%E9%87%8F%E6%9B%B2%E7%BA%BF%20%2F%20%E4%B8%8D%E5%B9%B3%E8%A1%A1%20%2F%20%E6%AF%92%E6%80%A7%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>五根轴是描述性的，不是最优性证明；真实产品是多轴混合体，且随版本漂移。缺的轴还有：费用与返佣（maker-taker 的符号直接影响接口轴）、tick 与最小申报单位、合规硬约束（报备、撤单率上限）——应写成轴的外部条件，而不是算法参数。跨经纪商比较时，五元组必须连同版本号一起审：标签不可迁移，规格才可迁移。后续各课默认五元组已冻结在规格文档里。</p><p><span class="marginnote">常见误区：以为「VWAP 算法都差不多，挑费率便宜的就行」。同名产品可以一个用静态历史量曲线、一个用实时反馈加暗池，恐慌日的成交质量能差出一个数量级。审规格要按五元组逐轴对齐并记录版本号，而不是比价格表。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>执行算法的差异写成五根轴：参照、决策、接口、场所、信息；名字只覆盖标签，不覆盖行为。</li><li>每根轴对应一个成本对象：参照对激励，接口对价差与排队，场所对冲击与填成，信息加决策对时机风险。</li><li>主干各算法是轴上的段落；后课沿轴深入：调度、暗池、竞价、波动、多资产，直到度量与最优控制。</li><li>名字相同而轴位不同的产品在体制切换时分化最大；规格与版本必须进审计文档。</li><li>费用、tick 与合规约束是轴外的硬边界。</li><li>出处：Harris, <em>Trading and Exchanges</em>；Kissell, <em>The Science of Algorithmic Trading and Portfolio Management</em>；对照 Perold, <em>Journal of Portfolio Management</em>, 1988。</li></ul>',5))])}const P=i(p,[["render",d]]);export{C as __pageData,P as default};
